import{_ as p,a0 as o,w as r,s as l,ao as d,I as s,x as a,a1 as n,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const T=JSON.parse('{"title":"在linux上使用交换文件扩展交换空间 | LCTT x X-CMD","titleTemplate":false,"description":"在linux上使用交换文件扩展交换空间 | LCTT (201506) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在linux上使用交换文件扩展交换空间 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在linux上使用交换文件扩展交换空间 | LCTT (201506) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201506/20150515 Extend Swap Space using Swap file in Linux","title":"在linux上使用交换文件扩展交换空间","tag":"201506","desc":""},"relativePath":"201506/20150515 Extend Swap Space using Swap file in Linux.md","filePath":"[post].md"}'),u={name:"201506/20150515 Extend Swap Space using Swap file in Linux.md"};function w(f,e,x,h,c,m){const t=o("Link");return r(),l("div",null,[e[13]||(e[13]=d(`<h1 id="在linux上使用交换文件扩展交换空间" tabindex="-1">在linux上使用交换文件扩展交换空间 <a class="header-anchor" href="#在linux上使用交换文件扩展交换空间" aria-label="Permalink to “在linux上使用交换文件扩展交换空间”">​</a></h1><p>想像一种情景，当我们的Linux系统用尽交换空间时，在这种情况下，我们想要使用swap分区扩展交换空间，但在某些情况下磁盘上已经没有可用的空闲分区了，致使我们不能把它扩大。</p><p>因此，在这种情况下，我们可以使用交换文件增加swap空间。</p><h3 id="以下是使用交换文件在linux上扩展swap空间的方法" tabindex="-1">以下是使用交换文件在Linux上扩展swap空间的方法 <a class="header-anchor" href="#以下是使用交换文件在linux上扩展swap空间的方法" aria-label="Permalink to “以下是使用交换文件在Linux上扩展swap空间的方法”">​</a></h3><p>让我们首先检查现有的交换空间/分区的大小，使用命令 ‘<strong>free -m‘</strong> 或者 ‘<strong>swapon -s</strong>‘</p><p><img src="http://www.linuxtechi.com/wp-content/uploads/2015/06/free-output-with-swap.jpg" alt=""> free-output-with-swap</p><p>我的交换分区大小是2 GB，我们将把交换空间扩展1GB。</p><h4 id="第一步-使用下面的dd命令创建大小为1gb交换文件" tabindex="-1">第一步：使用下面的dd命令创建大小为1GB交换文件 <a class="header-anchor" href="#第一步-使用下面的dd命令创建大小为1gb交换文件" aria-label="Permalink to “第一步：使用下面的dd命令创建大小为1GB交换文件”">​</a></h4><pre><code>[root@linuxtechi ~]# dd if=/dev/zero of=/swap_file bs=1G count=1
1+0 records in
1+0 records out
1073741824 bytes (1.1 GB) copied, 414.898 s, 2.6 MB/s
[root@linuxtechi ~]#
</code></pre><p>根据你的需要替换 ‘<strong>bs</strong>‘ 和 ‘<strong>count</strong>‘ 的大小.</p><h4 id="第二步-设置交换文件权限为600" tabindex="-1">第二步：设置交换文件权限为600 <a class="header-anchor" href="#第二步-设置交换文件权限为600" aria-label="Permalink to “第二步：设置交换文件权限为600”">​</a></h4><pre><code>[root@linuxtechi ~]# chmod 600 /swap_file
</code></pre><h4 id="第三步-用文件开启交换区-swap-file" tabindex="-1">第三步：用文件开启交换区（swap_file）#### <a class="header-anchor" href="#第三步-用文件开启交换区-swap-file" aria-label="Permalink to “第三步：用文件开启交换区（swap_file）####”">​</a></h4><p>用mkswap命令开启交换区</p><pre><code>[root@linuxtechi ~]# mkswap /swap_file
Setting up swapspace version 1, size = 1048572 KiB
no label, UUID=f7b3ae59-c09a-4dc2-ba4d-c02abb7db33b
[root@linuxtechi ~]#
</code></pre><h4 id="第四步-在fstab文件中添加交换文件条目" tabindex="-1">第四步：在fstab文件中添加交换文件条目 <a class="header-anchor" href="#第四步-在fstab文件中添加交换文件条目" aria-label="Permalink to “第四步：在fstab文件中添加交换文件条目”">​</a></h4><p>在fstab文件中添加以下条目，以便交换文件每次重启后互能继续使用.</p><pre><code>/swap_file  swap  swap  defaults  0 0
</code></pre><p><img src="http://www.linuxtechi.com/wp-content/uploads/2015/06/swap-file-fstab-entry.jpg" alt="swap-file-fstab-entry"></p><h4 id="第五步-用命令-mkswap-on-启用交换文件" tabindex="-1">第五步：用命令 ‘mkswap on’ 启用交换文件. <a class="header-anchor" href="#第五步-用命令-mkswap-on-启用交换文件" aria-label="Permalink to “第五步：用命令 ‘mkswap on’ 启用交换文件.”">​</a></h4><pre><code>[root@linuxtechi ~]# swapon /swap_file
[root@linuxtechi ~]#
</code></pre><h4 id="第六步-现在查看交换空间" tabindex="-1">第六步：现在查看交换空间 <a class="header-anchor" href="#第六步-现在查看交换空间" aria-label="Permalink to “第六步：现在查看交换空间”">​</a></h4><p><img src="http://www.linuxtechi.com/wp-content/uploads/2015/06/swap-space-after-extension.jpg" alt="swap-space-after-extension"></p><p><strong>Note</strong>: 为了避免出现意外的情况，如下所示使用swapoff命令关闭它，仅在需要使用时，使用步骤5所示的swapon命令，重新启用交换文件。</p><pre><code>[root@linuxtechi ~]# swapoff /swap_file
[root@linuxtechi ~]#
</code></pre><p>请分享您的宝贵意见或者评论此文章。</p><hr>`,27)),s("p",null,[e[1]||(e[1]=a("via: ",-1)),n(t,{href:"http://www.linuxtechi.com/extend-swap-space-using-swap-file-in-linux/"},{default:i(()=>[...e[0]||(e[0]=[a("http://www.linuxtechi.com/extend-swap-space-using-swap-file-in-linux/",-1)])]),_:1})]),s("p",null,[e[5]||(e[5]=a("作者：",-1)),n(t,{href:"http://www.linuxtechi.com/author/pradeep/"},{default:i(()=>[...e[2]||(e[2]=[a("Pradeep Kumar",-1)])]),_:1}),e[6]||(e[6]=a(" 译者：",-1)),n(t,{href:"https://github.com/strugglingyouth"},{default:i(()=>[...e[3]||(e[3]=[a("strugglingyouth",-1)])]),_:1}),e[7]||(e[7]=a(" 校对：",-1)),n(t,{href:"https://github.com/wxy"},{default:i(()=>[...e[4]||(e[4]=[a("wxy",-1)])]),_:1})]),s("p",null,[e[10]||(e[10]=a("本文由 ",-1)),n(t,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...e[8]||(e[8]=[a("LCTT",-1)])]),_:1}),e[11]||(e[11]=a(" 原创翻译，",-1)),n(t,{href:"https://linux.cn/"},{default:i(()=>[...e[9]||(e[9]=[a("Linux中国",-1)])]),_:1}),e[12]||(e[12]=a(" 荣誉推出",-1))])])}const _=p(u,[["render",w]]);export{T as __pageData,_ as default};
